incoming.template:
{#-
  NetBox -> IAG5 Inventory Template — NON-JUNOS / netmiko
  Filters: active devices, must have IP, must have a mapped platform,
           and platform is NOT Junos.
-#}

{% set platform_map = {
    'cisco-ios':         'cisco_ios',
    'cisco-ios-xe':      'cisco_xe',
    'cisco-ios-xr':      'cisco_xr',
    'cisco-nxos':        'cisco_nxos',
    'arista-eos':        'arista_eos',
    'paloalto-panos':    'paloalto_panos',
    'ubuntu-linux-18-04':'linux',
    'linux':             'linux',
    'ios':               'cisco_ios'
} %}

{% set credential_map = {
    'cisco_ios':      {'user': 'itential', 'password': 'password'},
    'cisco_xe':       {'user': 'itential', 'password': 'password'},
    'cisco_xr':       {'user': 'admin',    'password': 'password'},
    'cisco_nxos':     {'user': 'admin',    'password': 'CHANGEME_nxos'},
    'arista_eos':     {'user': 'admin',    'password': 'CHANGEME_eos'},
    'paloalto_panos': {'user': 'admin',    'password': 'CHANGEME_panos'},
    'linux':          {'user': 'ubuntu',   'password': 'CHANGEME_linux'}
} %}

{% set device_overrides = {
} %}

{% set default_creds = {'user': 'admin', 'password': 'CHANGEME_default'} %}

{% set netmiko_opts = {
    'banner_timeout':        60,
    'session_timeout':       300,
    'read_timeout_override': 600,
    'conn_timeout':          60,
    'global_delay_factor':   3,
    'enable_fast_mode':      true
} %}

[
{%- set ns = namespace(first=true) %}
{%- for device in body.results %}

  {%- set nb_platform = (device.platform.slug if device.platform else device.device_type.slug) or '' %}
  {%- set itential_platform = platform_map[nb_platform] if nb_platform in platform_map else '' %}

  {%- if device.primary_ip4 %}
    {%- set ip_address = device.primary_ip4.address.split('/')[0] %}
  {%- elif device.config_context and device.config_context.ipAddress %}
    {%- set ip_address = device.config_context.ipAddress %}
  {%- else %}
    {%- set ip_address = '' %}
  {%- endif %}

  {%- if device.name in device_overrides %}
    {%- set creds = device_overrides[device.name] %}
  {%- elif itential_platform in credential_map %}
    {%- set creds = credential_map[itential_platform] %}
  {%- else %}
    {%- set creds = default_creds %}
  {%- endif %}

  {%- if ip_address and itential_platform and device.status and device.status.value == 'active' %}
{{ "," if not ns.first else "" }}
{%- set ns.first = false %}
  {
    "name": "{{ device.name }}",
    "attributes": {
      "itential_host":           "{{ ip_address }}",
      "itential_port":           22,
      "itential_driver":         "netmiko",
      "itential_platform":       "{{ itential_platform }}",
      "itential_user":           "{{ creds.user }}",
      "itential_password":       "{{ creds.password }}",
      "itential_driver_options": {{ {'netmiko': netmiko_opts} | tojson }}
    },
    "tags": [
      "{{ (device.role.slug if device.role else 'unknown') }}",
      "{{ (device.site.slug if device.site else 'unknown') }}",
      "{{ (device.status.value if device.status else 'unknown') }}",
      "driver:netmiko",
      "platform:{{ itential_platform }}"
    ]
  }
  {%- endif %}
{%- endfor %}
]
